import os
import torch


class Config:
    """
    Configuration class for the Chatbot Arena Winner Prediction task.
    Defines file paths, model hyperparameters, and training settings.
    """

    # ==== General Settings ====
    SEED = 42
    DEBUG = False  # Set to True to run on a small subset for debugging
    DEBUG_SUBSET_SIZE = 1000

    # ==== File Paths ====
    # Input Metadata (generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Directories
    # Using idea_3 as the working directory for this iteration
    WORKING_DIR = "./working/idea_3"
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==== Data Parameters ====
    VOCAB_SIZE = 25000
    MAX_LEN = 192

    # ==== Model Architecture ====
    # Siamese Bi-LSTM with Late Interaction
    EMBEDDING_DIM = 300
    HIDDEN_DIM = 128
    DROPOUT = 0.5
    NUM_CLASSES = 3  # Winner A, Winner B, Tie

    # ==== Training Parameters ====
    BATCH_SIZE = 64
    LEARNING_RATE = 0.001
    EPOCHS = 15
    EARLY_STOPPING_PATIENCE = 3

    # ==== Compute ====
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 2

    @classmethod
    def setup(cls):
        """
        Creates necessary output directories.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def print_config(cls):
        """
        Prints the current configuration.
        """
        print("==== Configuration ====")
        print(f"Device: {cls.DEVICE}")
        print(
            f"Model: Emb={cls.EMBEDDING_DIM}, Hidden={cls.HIDDEN_DIM}, Vocab={cls.VOCAB_SIZE}"
        )
        print(
            f"Training: Batch={cls.BATCH_SIZE}, LR={cls.LEARNING_RATE}, Epochs={cls.EPOCHS}"
        )
        print(f"Paths: Train={cls.TRAIN_PATH}, Working={cls.WORKING_DIR}")
        print("=======================")
